import os                                                                                                                                                                                                                                                                                            
import logging                                                                                                                                                                                                                                                                                       
from typing import Optional                                                                                                                                                                                                                                                                          
from google import genai                                                                                                                                                                                                                                                                             
from google.genai import types, errors                                                                                                                                                                                                                                                               
                                                                                                                                                                                                                                                                                                         
logger = logging.getLogger(__name__) 

#its only job is connecting to Gemini API
class Gemini(): 
        DEFAULT_MODEL = "gemini-3.8-flash"                                                                                                                                                                                                                                                               
        
        def __init__(                                                                                                                                                                                                                                                                                    
            self,                                                                                                                                                                                                                                                                                        
            api_key: Optional[str] = None,                                                                                                                                                                                                                                                               
            model_name: Optional[str] = None,                                                                                                                                                                                                                                                            
            timeout_ms: int = 120_000,                                                                                                                                                                                                                                                                   
            client: Optional[genai.Client] = None,                                                                                                                                                                                                                                                       
        ):        
            self.__api_key = api_key or os.getenv("GEMINI_API_KEY")
            self.__model_name = model_name or self.DEFAULT_MODEL                                                                                                                                                                                                                                         
            self.__timeout_ms = timeout_ms 


        if not self.__api_key and client is None:                                                                                                                                                                                                                                                    
            logger.warning("GEMINI_API_KEY is not set. Gemini calls will fail unless a valid key is provided.")

            # Dependency Injection support: use provided client or create one                                                                                                                                                                                                                            
            if client is not None:                                                                                                                                                                                                                                                                       
                self.__client = client                                                                                                                                                                                                                                                                   
            else:                                                                                                                                                                                                                                                                                        
                self.__client = self.__create_default_client()                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                                                                         
        def __create_default_client(self) -> genai.Client:                                                                                                                                                                                                                                               
            """Helper method to construct a Google GenAI client with retry logic."""                                                                                                                                                                                                                     
            retry_options = types.HttpRetryOptions(                                                                                                                                                                                                                                                      
                attempts=3,                                                                                                                                                                                                                                                                              
                initial_delay=1.0,                                                                                                                                                                                                                                                                       
                max_delay=30.0,                                                                                                                                                                                                                                                                          
                exp_base=2.0,                                                                                                                                                                                                                                                                            
                jitter=1.0,                                                                                                                                                                                                                                                                              
                http_status_codes=[408, 429, 500, 502, 503, 504],                                                                                                                                                                                                                                        
            )                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                         
            return genai.Client(                                                                                                                                                                                                                                                                         
                api_key=self.__api_key or "missing_key",                                                                                                                                                                                                                                                 
                http_options=types.HttpOptions(                                                                                                                                                                                                                                                          
                    timeout=self.__timeout_ms,                                                                                                                                                                                                                                                           
                    retry_options=retry_options,                                                                                                                                                                                                                                                         
                ),                                                                                                                                                                                                                                                                                       
            ) 

        # @get model property                                                                                                                                                                                                                                      
        @property
        def model_name(self) -> str:
            """Returns the configured Gemini model name."""
            return self.__model_name
            
        def generate(self, prompt: str, system_instruction: Optional[str] = None) -> str:                                                                                                                                                                                                                
            """                                                                                                                                                                                                                                                                                          
            Sends the prompt to Gemini and returns the raw response text.                                                                                                                                                                                                                                
            """                                                                                                                                                                                                                                                                                          
            if not prompt or not prompt.strip():                                                                                                                                                                                                                                                         
                raise ValueError("Prompt cannot be empty.")                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                         
            try:                                                                                                                                                                                                                                                                                         
                # Build configuration                                                                                                                                                                                                                                                                    
                config = types.GenerateContentConfig(                                                                                                                                                                                                                                                    
                    temperature=0.1,                                                                                                                                                                                                                                                                     
                    max_output_tokens=65536,                                                                                                                                                                                                                                                             
                    response_mime_type="application/json",                                                                                                                                                                                                                                               
                )                                                                                                                                                                                                                                                                                        
                if system_instruction:                                                                                                                                                                                                                                                                   
                    config.system_instruction = system_instruction                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                                                                         
                # Execute API call                                                                                                                                                                                                                                                                       
                response = self.__client.models.generate_content(                                                                                                                                                                                                                                        
                    model=self.__model_name,                                                                                                                                                                                                                                                             
                    contents=prompt,                                                                                                                                                                                                                                                                     
                    config=config,                                                                                                                                                                                                                                                                       
                )                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                         
                # Validate that response contains text                                                                                                                                                                                                                                                   
                if not response.text:                                                                                                                                                                                                                                                                    
                    raise ValueError("Gemini returned an empty or null response.")                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                                                                         
                return response.text                                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                                                         
            except errors.ClientError as e:                                                                                                                                                                                                                                                              
                logger.error(f"Gemini Client Error ({e.code}): {e.message}")                                                                                                                                                                                                                             
                if e.code in (401, 403):                                                                                                                                                                                                                                                                 
                    raise PermissionError("Authentication failed. Invalid or expired Gemini API key.") from e                                                                                                                                                                                            
                elif e.code == 429:                                                                                                                                                                                                                                                                      
                    raise RuntimeError("Gemini API rate limit exceeded. Please try again later.") from e                                                                                                                                                                                                 
                else:                                                                                                                                                                                                                                                                                    
                    raise RuntimeError(f"Gemini Bad Request ({e.code}): {e.message}") from e                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                         
            except errors.ServerError as e:                                                                                                                                                                                                                                                              
                logger.error(f"Gemini Server Error ({e.code}): {e.message}")                                                                                                                                                                                                                             
                raise RuntimeError(f"Gemini server error ({e.code}). Please try again later.") from e                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                         
            except Exception as e:                                                                                                                                                                                                                                                                       
                logger.error(f"Unexpected error communicating with Gemini: {e}")                                                                                                                                                                                                                         
                raise 